package com.aadil.jobtracker.security;import com.aadil.jobtracker.UserRepository.UserRepository;import com.aadil.jobtracker.entity.UserEntity;import org.jspecify.annotations.NonNull;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.userdetails.User;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.security.core.userdetails.UserDetailsService;import org.springframework.security.core.userdetails.UsernameNotFoundException;import org.springframework.stereotype.Service;import java.util.List;@Servicepublic class CustomerUserDetailService implements UserDetailsService {    private final UserRepository userRepository;    public CustomerUserDetailService(UserRepository userRepository) {        this.userRepository = userRepository;    }    @Override    public @NonNull UserDetails loadUserByUsername(@NonNull String email) throws UsernameNotFoundException {        UserEntity user = userRepository.findByEmail(email).orElseThrow(()->new UsernameNotFoundException("Email NOT found: "+email));        return new User(email,user.getPassword(), List.of(new SimpleGrantedAuthority(user.getRoles())));    }}